def parse_numbers(input_string):
    result = []
    current_number = ""
    delimiter = "1"

    for char in input_string:
        if char.isdigit():
            current_number += char
        else:
            if current_number:
                result.append(current_number)
                current_number = ""
            delimiter = str(int(delimiter) + 1)

    if current_number:
        result.append(current_number)

    return ", ".join(result)

input_string = input("Numbers? ")
print(parse_numbers(input_string))
